#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
SV="$GSZ/server.js"; ST="$GSZ/views/admin/_shell_top.ejs"
MK="$GSZ/routes/marketing.js"; MV="$GSZ/views/admin/marketing.ejs"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step185: promotional email system (Admin > Marketing + unsubscribe)"
cp "$SV" "$SV.bak-step185-$TS"; cp "$ST" "$ST.bak-step185-$TS"
echo "    backups: server.js, _shell_top.ejs (*.bak-step185-$TS)"
NEWF=()
restore(){ echo "!! restoring"; cp "$SV.bak-step185-$TS" "$SV" 2>/dev/null||true; cp "$ST.bak-step185-$TS" "$ST" 2>/dev/null||true; for f in "${NEWF[@]}"; do rm -f "$f"; done; }
trap 'restore' ERR
echo "==> writing new files"
echo "" | base64 -d > "$MK"; NEWF+=("$MK")
echo "" | base64 -d > "$MV"; NEWF+=("$MV")
echo "==> DB migration"
DBJS=$(mktemp /tmp/db185.XXXXXX.js); echo "" | base64 -d > "$DBJS"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" GSZ_ENV="$GSZ/.env" node "$DBJS" )
rm -f "$DBJS"
echo "==> wiring (server.js mount + admin nav)"
P=$(mktemp /tmp/p185.XXXXXX.js); echo "" | base64 -d > "$P"
NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$SV" && echo "    server.js ok"
NODE_PATH="$GSZ/node_modules" node --check "$MK" && echo "    marketing.js ok"
for V in "$MV" "$ST"; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$V','utf8'),{filename:'$V'});console.log('    ejs ok: '+'$V'.replace('$GSZ/',''))"; done
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/admin/login || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    admin $CODE"; false; }
echo "    admin up: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step185 OK  Admin > Marketing lets you compose + preview + send a promo to all opted-in customers; every email has a one-click Unsubscribe (/unsubscribe). Order/account emails are untouched."
